INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4010de24-d269-41c7-a2d7-ca6c7f0b3d9b', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "a473e96f-1f88-4fdc-b2b3-895a39303594", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "f04b5393-ee97-413d-9e62-8fadc26f8239", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "aab571a4-a24f-47b7-953a-742d04e6ac7d", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "0163ce15-32e1-4324-abbb-7ca67969b1f5", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "a8c354b6-3ff7-4664-8fc5-f4cecff3f58d", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "c76025ec-5c4a-422f-bdf3-f5c8adcf4060", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "0e5311ed-479e-4ec9-8706-894e75697f52", "text": "Igaz", "isCorrect": true}, {"id": "127b3208-7474-4a9d-bb0a-560116e67720", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d983c94c-1161-4e03-8b61-bbb5e64ba1ac", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "a29e8fe5-d169-4612-a3a5-1bd9e4838134", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "34609ce1-84f4-40a3-a03e-f552aa6025cf", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "ed938d97-117c-47ec-8eba-9f5f613b4987", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "17c19b08-5d93-434e-b1ce-db47a76c48af", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "4ff6222f-b772-4a16-80c9-4584d915f9dd", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "171b5f70-0bb5-4313-becd-717195bc8976", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "73aeb042-108d-46fa-b019-215cb86b5cf0", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "3160db8e-f047-4a83-86d4-92770b03a710", "text": "Igaz", "isCorrect": true}, {"id": "d85e025c-f4f8-40b7-9313-753103ecf7ad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ef1282d-b472-4d16-b02b-26c76ea58809", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ad6dae84-9783-4de5-919e-dc4b4e79f6e9', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "be6af655-cb94-4c34-88a9-17a74ac7f57f", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "da3cf6c5-da97-42bd-aa7f-f58c95bbf170", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "dc721b10-730b-46a6-95b5-cd481a259fca", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "ff964e09-c2d0-4849-8718-4b661007a2b6", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "0d8b3135-a8ed-4868-950c-793ff2a15461", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "b82fb686-1893-4ae8-a6e9-956d86ac9124", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "fcd15f6f-dbda-4297-bc92-f815ed88182a", "text": "Igaz", "isCorrect": true}, {"id": "814d998a-47e1-4123-94ba-10c88c06f0b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "abb7e960-cfbc-46dd-b02c-497153bc9800", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "172d0194-c30c-4eae-8a48-3bfee5936fc3", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "6ab6e6ca-94c0-4e46-b19b-4fe7aa42fd7a", "text": "Sudoku", "isCorrect": true}, {"id": "8a8a4945-8486-427d-ba6a-18c1e722805a", "text": "Fócsoport", "isCorrect": false}, {"id": "aba285ca-9e98-4797-b82c-6fd1ba94ef19", "text": "Futóverseny", "isCorrect": false}, {"id": "f4d4a075-fae0-4c26-95f8-0cf4716d0586", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "6500174b-00b9-49d3-adf5-ce335a5d71bd", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "596d65ff-8323-4746-bd43-f3ee00e601d3", "text": "Igaz", "isCorrect": true}, {"id": "4a857203-cfc3-4041-94fa-830c21ea30ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "724c2a3d-2e2d-4803-9793-17e3840e0524", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "7fd2af35-82db-4ca5-b3b1-d020e42ce1a8", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "7f2968bb-2fa0-4ae2-8743-6eaedb92aba3", "text": "Igaz", "isCorrect": true}, {"id": "0b9f91f3-b49e-4e10-b56f-8d9bd496c1df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('72141124-1359-4a39-9307-3f4d8ac14d3c', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "4873535d-53c6-4d0d-a864-d575a5159a5d", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "65e77195-d9f0-48ad-820c-c230c2b0b2c2", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "4bf7e56c-5195-44fb-a352-5a7008f5f3c4", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "3449801c-aae2-42c8-aeea-19c755a639de", "text": "2/4", "isCorrect": false}, {"id": "66047b2f-b97c-4fae-a3b4-28425e63c4cd", "text": "4/8", "isCorrect": false}, {"id": "ef280ee4-b0b5-4e51-afc5-e1043ad8f722", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "dd1df16f-0714-42ef-9fd7-409b69ebb5b4", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "538616cc-d636-4f29-9b45-fbb79a133ead", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "589326ff-f00f-4a4d-bf8a-b5d2d5762b4d", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "e49f74a1-601f-40b3-a8f1-cd153cca6fac", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "a854cd2a-4845-4ed6-85a7-39b31d7d9b28", "text": "Igaz", "isCorrect": true}, {"id": "22e8556e-ee42-4487-964c-cf7f07cddf3b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cf1ec318-ea38-4184-b171-75b4a9e8a04a", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "adab8f44-a814-4e2c-ae3c-2a2fa2e6275e", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "0dffd422-69cd-493c-9f2b-5e28d5f6087f", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "b7c840a4-3175-464e-98f2-e1c0972f9748", "text": "Igaz", "isCorrect": true}, {"id": "85d98b57-f87f-40ae-b6ae-df530e6bbc0b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8774d877-8b4a-4bed-b216-5452bcd49154", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c6946c75-f433-4f87-aec1-671ddb93ea67', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "b72334cf-0e6c-4618-872e-44707dea2060", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "73fd7c0b-60e7-453a-aeac-8e323397a737", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "c25358fd-5b52-451a-917c-8ba560dcace6", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "8c674739-4e6a-4ced-b197-9d01b76b8702", "text": "Igaz", "isCorrect": true}, {"id": "d3d49a38-dccc-4a15-b41f-b3f720e8adf6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f67b6629-9ab0-4f14-9210-f0d3ed864fa7", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "f800e59c-bb2c-46c8-b406-88086dd10f77", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "1206ab57-cd19-44b4-9554-b89061c451ea", "text": "-8", "isCorrect": true}, {"id": "2587654a-3d91-4b06-9efb-6764c40c9410", "text": "-15", "isCorrect": false}, {"id": "878abc1d-28b3-4390-9eb5-fbd4f0e26e40", "text": "Egyenlőek", "isCorrect": false}, {"id": "0d86d4c1-292a-43a3-a1e5-fedcfa2d2e81", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "f6edd047-e805-4488-83b8-2dac25b7c7ea", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "40486bb0-4761-4256-af9d-48d1fb3f13de", "text": "Igaz", "isCorrect": true}, {"id": "a23f0346-a627-4cf3-8da4-208d4d9acb1c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6451d51d-f4c6-4375-81e4-3ba4e4a4cf19", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d22ff88a-1858-4b89-8b23-8c8b46218635', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "39214a72-32a4-4f09-a27c-0019564cc9d5", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "def46b1d-1f31-446a-a021-c6eb122b15fc", "text": "Pozitív (+)", "isCorrect": true}, {"id": "593d308b-d99f-4ba5-95b6-91e0861221b0", "text": "Negatív (-)", "isCorrect": false}, {"id": "65801bde-6f18-4b96-9a42-86e033c5c9f5", "text": "Mindig 0", "isCorrect": false}, {"id": "32fecaba-0543-4666-b0b7-c6b268d05e74", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "1c828ff7-0531-4b65-985c-f798075d77dc", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "79826fb9-56f6-4126-ab72-8c8cd72095ab", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "0d25b530-057d-4669-a0ba-cefbc3bdcb45", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "828ed9b2-97c1-4582-836f-dee16df4cd6e", "text": "Igaz", "isCorrect": true}, {"id": "0d836061-8b3c-4415-9378-3adf9f17145d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dcffc5e6-5951-49b0-9077-4dcc5d4b1011", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "5b91182d-7520-4a4b-aa82-e0a3a8cc70f4", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "1b02c22a-30ca-4bf1-a3aa-9b80be12eb41", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "27c2efb1-1cd8-4f7c-bb0f-5d30e7a4c804", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3c8bff2e-a08a-41c5-b412-2321f3cf1fe4", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('725a2337-1f23-46d8-a188-a3970e21787e', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4236afca-7809-4dd3-9172-003a07797295", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "7712d26c-51bf-4895-9c33-58b96896793c", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "992df55f-8ed0-47ac-acf0-577eb814f6bb", "text": "Pozitív", "isCorrect": true}, {"id": "864c7204-008e-4899-a18b-62994de67b95", "text": "Negatív", "isCorrect": false}, {"id": "7930cc53-8ad9-409b-b82b-328bba364048", "text": "Nulla", "isCorrect": false}, {"id": "dd3e2572-53f0-4f84-87f6-2e68ea20bf21", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "5cc58219-c3d8-4605-bac0-bbec568fb454", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "40bf86e3-67ba-421d-ae36-de992b7fc17b", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "6bbca850-f899-41ad-af4b-b868598b87ab", "text": "Igaz", "isCorrect": true}, {"id": "d42ed661-97e7-44a6-b2c7-ec1de66b13c3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44d29571-4097-4bed-aa00-5bf4ae4ab086", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "448fe337-a19e-4717-a278-41a751ae3c99", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "fd90fcd8-1329-4fc9-8cc1-a7222b2a085e", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "51ff48ea-ba7a-482f-94f9-65adf53c190f", "text": "Igaz", "isCorrect": true}, {"id": "ad2e298b-9c8f-41c0-9338-ae8910a31642", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('78463bc6-1027-4271-8ff6-6f11abb4e8b4', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "bc8b9853-ea1d-4766-9ac5-fad62a84f990", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "b858822f-5771-4e69-bc4a-a3a4260ae2e7", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "fdc3b386-d7ea-42f9-8747-8d7fcbe27031", "text": "Mindig negatív", "isCorrect": false}, {"id": "538bb19d-6f2d-452d-8d2c-164a56087856", "text": "Mindig pozitív", "isCorrect": false}, {"id": "90982894-8d53-4822-b1cd-d7a027b9b94c", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "2b000d54-03a9-49fe-a83b-4e6802cd1b34", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "8a6efc9a-86c5-4c46-96ec-a285bfa09f95", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "63e0b20b-83a6-4379-8eaf-946eae3176c1", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "3a085bd0-6f57-40b6-8501-44d0bb8ce5d2", "text": "Igaz", "isCorrect": true}, {"id": "b36e2cfd-4844-4a1c-bdb5-daa857a3c6b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "254006fb-f144-47c7-9a24-3338ca6454ae", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "67600220-b325-43f9-9ea5-6bc5e7104cb1", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "d8dc6cc5-e8f6-448e-824d-0ea2e6871d80", "text": "Igaz", "isCorrect": true}, {"id": "7924d062-e1f2-48d7-8707-9ab1aea8ffbe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e7088e5-ab57-42be-995f-f3f66914f967", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5663e2b0-8d75-475d-babc-1cfc5cf9e82c', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "22109585-fa3e-4e62-9820-7eb97d4940d0", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "7607f5b7-10ea-43c8-b469-d1080f78caf2", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "8d940700-4aeb-4098-afb3-3b6171782bac", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "18e6fbc0-42c6-434a-8af9-c871f4e361bf", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "35594687-4a84-49c2-9a2a-2977469a1f0c", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "2a7e7499-09bf-4561-ab56-be267c2b8445", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "123eccf9-dfb3-444a-bae9-905cb64366de", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "dc1f76d9-2a08-4aa9-bd92-9b7164e28573", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "82de5695-e432-410e-b04f-5cc9885f629a", "text": "Igaz", "isCorrect": true}, {"id": "9551585f-ff65-4651-86fd-6eba7ce6fcf4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "226e3f94-3c69-4c18-9767-5f87f6ee3e3c", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "e6441fb8-756e-4dc7-a884-cb7a16a042f8", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "2256d841-f2fe-408b-8d52-c5b9d34917c2", "text": "Igaz", "isCorrect": true}, {"id": "478b05de-0635-444b-80fc-6f34704ee22f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "568140b4-6980-4b97-8746-6d8ae24a5890", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('354559fa-d9fb-42c8-a670-2db8bbb874d9', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "838d1934-9a85-4aae-b72f-093becc7c9e4", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "593b6dee-2284-430c-8db9-8b55124aafb4", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "6ca2e4bb-5961-48d5-8097-aa370eec14c0", "text": "Szögmérőt", "isCorrect": false}, {"id": "4c93f30c-fa7e-4b95-841f-bdf514a932d6", "text": "Körzőt", "isCorrect": false}, {"id": "3292bf19-83a3-4e1c-a978-7dfad3701e00", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "fb14f959-6604-4711-8f54-0c399c2012ef", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "77a84d2e-2b79-40dd-82cc-112cb452eead", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "8d84e518-1a69-4092-a24b-43bfaa5e9cf9", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "f8dafbf1-19de-4dcf-8afa-c08e3ea7eb33", "text": "Igaz", "isCorrect": true}, {"id": "88d78078-14d1-4a56-8ffb-ed173eec3f4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92408336-8320-4ce7-8159-a7cef74ad603", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3bc80ffa-66d1-4c13-957f-a5483dfa8673", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "0f5ea5a3-0de9-4f8e-bffd-b9862b09ed1f", "text": "Igaz", "isCorrect": false}, {"id": "4d4ef23f-7156-4907-905a-c2abd54d24cd", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "2b063c1f-4917-49d1-95c0-eaa737f8b57b", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());